def transform(grid):
    h, w = len(grid), len(grid[0])
    m = max(max(row) for row in grid)
    best_start = 1
    best_score = -1

    for start in range(1, m + 1):
        score = 0
        for r in range(h):
            for c in range(w):
                expected = (start - 1 + c) % m + 1
                if grid[r][c] == expected:
                    score += 1
        if score > best_score:
            best_score = score
            best_start = start

    pattern = [(best_start - 1 + c) % m + 1 for c in range(w)]
    return [pattern[:] for _ in range(h)]
